package com.whaa.shop.payment.infrastructure;
import com.alipay.api.*;import com.alipay.api.internal.util.AlipaySignature;import com.alipay.api.domain.AlipayTradePagePayModel;import com.alipay.api.request.AlipayTradePagePayRequest;import com.whaa.shop.common.exception.BusinessException;import com.whaa.shop.payment.application.PaymentGateway;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.stereotype.Component;import java.math.BigDecimal;import java.util.Map;
@Component @ConditionalOnProperty(name="whaashop.alipay.enabled",havingValue="true") public class AlipaySandboxGateway implements PaymentGateway {private static final Logger log=LoggerFactory.getLogger(AlipaySandboxGateway.class);private final AlipayClient client;private final String publicKey,notifyUrl,returnUrl;
 public AlipaySandboxGateway(@Value("${whaashop.alipay.gateway}")String gateway,@Value("${whaashop.alipay.app-id}")String appId,@Value("${whaashop.alipay.private-key}")String privateKey,@Value("${whaashop.alipay.public-key}")String publicKey,@Value("${whaashop.alipay.notify-url}")String notifyUrl,@Value("${whaashop.alipay.return-url}")String returnUrl){this.client=new DefaultAlipayClient(gateway,appId,privateKey,"json","UTF-8",publicKey,"RSA2");this.publicKey=publicKey;this.notifyUrl=notifyUrl;this.returnUrl=returnUrl;}
 public PaymentRequestResult create(String orderNo,BigDecimal amount,String subject){try{AlipayTradePagePayModel m=new AlipayTradePagePayModel();m.setOutTradeNo(orderNo);m.setTotalAmount(amount.toPlainString());m.setSubject(subject);m.setProductCode("FAST_INSTANT_TRADE_PAY");AlipayTradePagePayRequest r=new AlipayTradePagePayRequest();r.setBizModel(m);r.setNotifyUrl(notifyUrl);r.setReturnUrl(returnUrl);String html=client.pageExecute(r).getBody();return new PaymentRequestResult("ALIPAY",null,html);}catch(AlipayApiException e){log.error("Failed to create Alipay payment: orderNo={}, amount={}",orderNo,amount,e);throw new BusinessException("创建支付宝支付失败: "+e.getErrMsg());}}
 public boolean verify(Map<String,String> callback){try{return AlipaySignature.rsaCheckV1(callback,publicKey,"UTF-8","RSA2");}catch(AlipayApiException e){log.error("Failed to verify Alipay callback: outTradeNo={}, tradeNo={}",callback.get("out_trade_no"),callback.get("trade_no"),e);return false;}}}
